package frontier

import (
	"context"

	"github.com/redis/go-redis/v9"
)

// Frontier manages the shared "URL frontier" for a distributed web crawler.
// Newly discovered URLs are deduped against a RedisBloom filter before being
// pushed onto the pending-URL queue that downstream workers pull from.
type Frontier struct {
	client           *redis.Client
	seenFilterKey    string // RedisBloom filter of already-seen URLs
	frontierQueueKey string // list of URLs pending crawl
}

func NewFrontier(client *redis.Client, seenFilterKey, frontierQueueKey string) *Frontier {
	return &Frontier{
		client:           client,
		seenFilterKey:    seenFilterKey,
		frontierQueueKey: frontierQueueKey,
	}
}

// EnqueueURL dedups a newly discovered URL against the bloom filter and,
// if it hasn't been seen before, pushes it onto the frontier queue.
func (f *Frontier) EnqueueURL(ctx context.Context, url string) error {
	// Round-trip #1: membership check against the bloom filter.
	exists, err := f.client.Do(ctx, "BF.EXISTS", f.seenFilterKey, url).Bool()
	if err != nil {
		return err
	}
	if exists {
		// Already seen by some other worker -> nothing to do.
		return nil
	}

	// Round-trip #2: mark the URL as seen in the bloom filter.
	if err := f.client.Do(ctx, "BF.ADD", f.seenFilterKey, url).Err(); err != nil {
		return err
	}

	// Round-trip #3: push the URL onto the frontier queue for workers to pick up.
	return f.client.RPush(ctx, f.frontierQueueKey, url).Err()
}
